      "path": "scripts/validation/sandbox-runner.ts",
      "content": "import { execFile } from 'node:child_process'\nimport { createHash } from 'node:crypto'\nimport { promisify } from 'node:util'\n\nimport {\n  appendValidationEvent,\n  parseValidationReport,\n  type FailureAttribution,\n  type ValidationReport,\n} from '../../src/lib/validation-report'\nimport {\n  summarizeSandboxExecution,\n  type DockerCommand,\n  type LinuxSandboxPlan,\n  type SandboxExecutionSummary,\n  type SandboxStepId,\n  type SandboxStepResult,\n} from './linux-sandbox'\n\nconst execFileAsync = promisify(execFile)\n\ninterface ExecutorResult {\n  exitCode: number | null\n  timedOut: boolean\n  stdout: string\n  stderr: string\n}\n\ntype Executor = (\n  command: DockerCommand,\n  id: SandboxStepId | 'remove-container' | 'remove-volume',\n  timeoutMs: number,\n) => Promise<ExecutorResult>\n\nexport interface SandboxRunResult {\n  report: ValidationReport\n  summary: SandboxExecutionSummary\n  results: SandboxStepResult[]\n  cleanupFailures: Array<'remove-container' | 'remove-volume'>\n}\n\nasync function defaultExecutor(\n  command: DockerCommand,\n  _id: SandboxStepId | 'remove-container' | 'remove-volume',\n  timeoutMs: number,\n): Promise<ExecutorResult> {\n  try {\n    const result = await execFileAsync(command.file, command.args, {\n      encoding: 'utf8',\n      timeout: timeoutMs,\n      killSignal: 'SIGKILL',\n      maxBuffer: 16 * 1024 * 1024,\n    })\n    return { exitCode: 0, timedOut: false, stdout: result.stdout, stderr: result.stderr }\n  } catch (error) {\n    const failure = error as Error & { code?: number | string, killed?: boolean, stdout?: string, stderr?: string }\n    return {\n      exitCode: typeof failure.code === 'number' ? failure.code : null,\n      timedOut: failure.killed === true || failure.code === 'ETIMEDOUT',\n      stdout: failure.stdout ?? '',\n      stderr: failure.stderr ?? '',\n    }\n  }\n}\n\nfunction fingerprint(report: ValidationReport, code: string): string {\n  return createHash('sha256')\n    .update(`${report.repository.id}:${report.repository.sourceSha}:${report.target.dshVersion}:${code}`)\n    .digest('hex')\n}\n\nfunction appendFailure(\n  report: ValidationReport,\n  status: 'install_failed' | 'runtime_failed' | 'smoke_failed',\n  summary: SandboxExecutionSummary,\n  at: string,\n): ValidationReport {\n  return appendValidationEvent(report, {\n    stage: status === 'install_failed' ? 'installation' : status === 'runtime_failed' ? 'runtime' : 'smoke',\n    status,\n    at,\n    code: summary.code,\n    reason: summary.code,\n    attribution: summary.attribution as FailureAttribution,\n    fingerprint: fingerprint(report, summary.code),\n  })\n}\n\nfunction assertBinding(report: ValidationReport, plan: LinuxSandboxPlan): void {\n  if (report.currentStatus !== 'structure_passed'\n    || report.repository.id !== plan.binding.repositoryId\n    || report.repository.sourceSha !== plan.binding.sourceSha\n    || report.target.dshVersion !== plan.binding.dshVersion\n    || report.target.platform !== plan.binding.platform\n    || report.target.validatorVersion !== plan.binding.validatorVersion) {\n    throw new Error('Sandbox report binding does not match the command plan')\n  }\n}\n\nexport async function executeLinuxSandboxPlan(\n  structureReport: ValidationReport,\n  plan: LinuxSandboxPlan,\n  {\n    executor = defaultExecutor,\n    now = () => new Date().toISOString(),\n  }: { executor?: Executor, now?: () => string } = {},\n): Promise<SandboxRunResult> {\n  assertBinding(structureReport, plan)\n  let report = appendValidationEvent(structureReport, {\n    stage: 'sandbox',\n    status: 'queued',\n    at: now(),\n  })\n  report = appendValidationEvent(report, {\n    stage: 'sandbox',\n    status: 'running',\n    at: now(),\n  })\n\n  const results: SandboxStepResult[] = []\n  const cleanupFailures: SandboxRunResult['cleanupFailures'] = []\n  try {\n    for (const step of plan.steps) {\n      const execution = await executor(step.command, step.id, step.timeoutMs)\n      results.push({\n        stepId: step.id,\n        exitCode: execution.exitCode,\n        timedOut: execution.timedOut,\n      })\n      if (execution.timedOut || execution.exitCode !== 0) break\n\n      if (step.id === 'install-plugin') {\n        report = appendValidationEvent(report, { stage: 'installation', status: 'install_passed', at: now() })\n      } else if (step.id === 'load') {\n        report = appendValidationEvent(report, { stage: 'runtime', status: 'runtime_passed', at: now() })\n      } else if (step.id === 'postflight') {\n        report = appendValidationEvent(report, { stage: 'smoke', status: 'smoke_passed', at: now() })\n      }\n    }\n\n    const summary = summarizeSandboxExecution(results)\n    if (summary.finalStatus === 'verified') {\n      report = appendValidationEvent(report, { stage: 'final', status: 'verified', at: now() })\n    } else if (summary.finalStatus === 'inconclusive') {\n      report = appendValidationEvent(report, {\n        stage: 'sandbox',\n        status: 'inconclusive',\n        at: now(),\n        code: summary.code,\n        reason: summary.code,\n        attribution: summary.attribution,\n      })\n    } else {\n      report = appendFailure(report, summary.failedStatus!, summary, now())\n      report = appendValidationEvent(report, {\n        stage: 'final',\n        status: 'failed',\n        at: now(),\n        code: summary.code,\n        reason: summary.code,\n        attribution: summary.attribution,\n        fingerprint: fingerprint(report, summary.code),\n      })\n    }\n    return { report: parseValidationReport(report), summary, results, cleanupFailures }\n  } finally {\n    for (const cleanup of plan.cleanup) {\n      const execution = await executor(cleanup.command, cleanup.id, 30_000)\n      if (execution.exitCode !== 0 && cleanup.id === 'remove-volume') cleanupFailures.push(cleanup.id)\n    }\n  }\n}\n"
    },
    {
      "path": "packages/dsh-plugins-store/src/installer.js",
      "content": "const REPOSITORY_ID = /^[A-Za-z0-9][A-Za-z0-9:_./-]{0,127}$/\nconst REPOSITORY_FULL_NAME = /^[A-Za-z0-9](?:[A-Za-z0-9_.-]{0,99})\\/[A-Za-z0-9](?:[A-Za-z0-9_.-]{0,99})$/\nconst NPM_PACKAGE = /^(?:@[A-Za-z0-9](?:[A-Za-z0-9._-]{0,99})\\/)?[A-Za-z0-9](?:[A-Za-z0-9._-]{0,99})(?:@[A-Za-z0-9^~<>=*+._-][A-Za-z0-9^~<>=*+._-]{0,127})?$/\nconst MAX_BODY_BYTES = 4096\n\nfunction assertInstallPlan(plan) {\n  if (plan === null || typeof plan !== 'object' || plan.executable !== true) {\n    throw new Error('安装计划不可执行')\n  }\n  if (plan.source !== 'github' && plan.source !== 'npm') {\n    throw new Error('安装来源无效')\n  }\n  if (typeof plan.target !== 'string') throw new Error('安装目标无效')\n  if (!Array.isArray(plan.args)\n    || plan.args.length !== 5\n    || plan.args[0] !== 'plugin'\n    || plan.args[1] !== '--profile'\n    || plan.args[2] !== 'web'\n    || plan.args[3] !== 'add'\n    || typeof plan.args[4] !== 'string') {\n    throw new Error('安装参数无效')\n  }\n\n  const specifier = plan.args[4]\n  if (plan.source === 'github') {\n    const reference = /^github:([^#]+)(?:#([A-Za-z0-9][A-Za-z0-9_.:-]{0,127}))?$/i.exec(specifier)\n    if (!reference || !REPOSITORY_FULL_NAME.test(reference[1])\n      || reference[1].toLowerCase() !== plan.target.toLowerCase()) {\n      throw new Error('GitHub 安装目标无效')\n    }\n  } else {\n    const packageName = specifier.startsWith('npm:') ? specifier.slice(4) : specifier\n    if (!NPM_PACKAGE.test(packageName) || packageName !== plan.target) {\n      throw new Error('npm 安装目标无效')\n    }\n  }\n\n  return {\n    source: plan.source,\n    target: plan.target,\n    args: [...plan.args],\n  }\n}\n\nfunction assertRepositoryId(repositoryId) {\n  if (typeof repositoryId !== 'string' || !REPOSITORY_ID.test(repositoryId)) {\n    throw new Error('目录项目 ID 无效')\n  }\n}\n\nexport function sendJson(response, status, body) {\n  response.statusCode = status\n  response.setHeader('Content-Type', 'application/json; charset=utf-8')\n  response.setHeader('Cache-Control', 'no-store')\n  response.end(JSON.stringify(body))\n}\n\nexport function readJsonBody(request) {\n  return new Promise((resolve, reject) => {\n    let body = ''\n    let exceeded = false\n    request.on('data', (chunk) => {\n      if (exceeded) return\n      body += chunk.toString('utf8')\n      if (Buffer.byteLength(body) > MAX_BODY_BYTES) {\n        exceeded = true\n        reject(new Error('请求内容过大'))\n      }\n    })\n    request.on('end', () => {\n      if (exceeded) return\n      try {\n        resolve(JSON.parse(body))\n      } catch {\n        reject(new Error('请求内容不是有效 JSON'))\n      }\n    })\n    request.on('error', reject)\n  })\n}\n\nfunction isLoopbackAddress(address) {\n  if (typeof address !== 'string') return false\n  const normalized = address.replace(/^::ffff:/i, '')\n  return normalized === '::1' || normalized === '127.0.0.1' || normalized === '0:0:0:0:0:0:0:1'\n}\n\nfunction isLocalHost(value) {\n  if (typeof value !== 'string') return false\n  try {\n    const hostname = new URL(`http://${value}`).hostname\n    return hostname === 'localhost' || hostname === '127.0.0.1' || hostname === '[::1]' || hostname === '::1'\n  } catch {\n    return false\n  }\n}\n\nfunction isLocalRequest(request) {\n  return isLoopbackAddress(request.socket?.remoteAddress)\n    && isLocalHost(request.headers.host)\n}\n\nexport function isAuthorizedLocalRequest(request) {\n  return isLocalRequest(request)\n}\n\nexport function isAuthorizedRequest(request) {\n  if (!isLocalRequest(request)) return false\n\n  const origin = request.headers.origin\n  if (typeof origin !== 'string' || origin.length === 0) return false\n  try {\n    return new URL(origin).host === request.headers.host\n  } catch {\n    return false\n  }\n}\n\nexport async function installPlan(plan, {\n  runner,\n  execPath,\n  cliPath,\n  signal,\n}) {\n  const safePlan = assertInstallPlan(plan)\n  if (typeof runner !== 'function' || !execPath || !cliPath) {\n    throw new Error('DSH 安装器不可用')\n  }\n\n  const { stdout, stderr } = await runner(execPath, [cliPath, ...safePlan.args], signal)\n  const output = [stdout, stderr]\n    .map((value) => value.trim())\n    .filter(Boolean)\n    .join('\\n')\n\n  return {\n    source: safePlan.source,\n    target: safePlan.target,\n    output: output.slice(-8000),\n  }\n}\n\nexport function createInstallHandler({ install }) {\n  let installing = false\n\n  return async (request, response) => {\n    if (request.method !== 'POST') {\n      response.setHeader('Allow', 'POST')\n      sendJson(response, 405, { ok: false, message: '仅支持 POST' })\n      return\n    }\n    if (!request.headers['content-type']?.toLowerCase().startsWith('application/json')) {\n      sendJson(response, 415, { ok: false, message: '仅接受 JSON 请求' })\n      return\n    }\n    if (!isAuthorizedRequest(request)) {\n      sendJson(response, 403, { ok: false, message: '拒绝跨来源安装请求' })\n      return\n    }\n\n    let repositoryId\n    let plan\n    try {\n      const body = await readJsonBody(request)\n      repositoryId = body?.repositoryId\n      plan = body?.install\n      assertRepositoryId(repositoryId)\n      plan = assertInstallPlan(plan)\n    } catch (error) {\n      sendJson(response, 400, {\n        ok: false,\n        message: error instanceof Error ? error.message : String(error),\n      })\n      return\n    }\n\n    if (installing) {\n      sendJson(response, 409, { ok: false, message: '已有插件正在安装，请稍后重试' })\n      return\n    }\n\n    installing = true\n    try {\n      const result = await install({ repositoryId, ...plan })\n      sendJson(response, 200, {\n        ok: true,\n        repositoryId,\n        source: plan.source,\n        target: plan.target,\n        needsRestart: true,\n        output: result.output,\n      })\n    } catch (error) {\n      sendJson(response, 502, {\n        ok: false,\n        message: error instanceof Error ? error.message : String(error),\n      })\n    } finally {\n      installing = false\n    }\n  }\n}\n"
    },
    {
      "path": "src/lib/validation.ts",
      "content": "import type { ProjectType } from './classification'\nimport { parseSourceClassification, type SourceClassification } from './source-classification'\n\nexport const CURRENT_VALIDATION_TARGET = Object.freeze({\n  dshVersion: '0.1.0-rc.6',\n  platform: 'linux-x64',\n  validatorVersion: '0.1.2',\n} as const)\n\nexport const VALIDATION_STAGE_DEFINITIONS = Object.freeze([\n  { id: 'discovery', label: '市场发现' },\n  { id: 'identification', label: '归类识别' },\n  { id: 'structure', label: '结构检查' },\n  { id: 'sandbox', label: '实机验证' },\n] as const)\n\nexport const VALIDATION_STATUS_DEFINITIONS = Object.freeze([\n  { id: 'unrecognized', label: '待识别' },\n  { id: 'check-pending', label: '待结构检查' },\n  { id: 'check-running', label: '结构检查中' },\n  { id: 'check-failed', label: '结构检查失败' },\n  { id: 'sandbox-pending', label: '待实机验证' },\n  { id: 'sandbox-running', label: '实机验证中' },\n  { id: 'sandbox-failed', label: '实机验证失败' },\n  { id: 'verified', label: '已验证' },\n  { id: 'expired', label: '需重新验证' },\n  { id: 'recorded', label: '已有验证记录' },\n  { id: 'retrying', label: '自动重试中' },\n  { id: 'capability-pending', label: '等待验证器' },\n  { id: 'external-dependency', label: '等待外部依赖' },\n  { id: 'inconclusive', label: '需要复核' },\n  { id: 'security-review', label: '安全复核中' },\n  { id: 'not-applicable', label: '非插件验证范围' },\n] as const)\n\nexport type ValidationOverall = typeof VALIDATION_STATUS_DEFINITIONS[number]['id']\nexport type ValidationRecordDisposition = 'verified' | 'auto_failed' | 'retryable' | 'capability_pending' | 'external_dependency_pending' | 'manual_review'\nexport type ValidationStageId = typeof VALIDATION_STAGE_DEFINITIONS[number]['id']\nexport type ValidationStageStatus = 'pending' | 'running' | 'passed' | 'failed' | 'inconclusive' | 'quarantined' | 'skipped'\nexport type ValidationTone = 'neutral' | 'info' | 'running' | 'success' | 'warning' | 'danger'\n\nexport interface ValidationStageEvidence {\n  status: ValidationStageStatus\n  checkedAt?: string\n  reportUrl?: string\n  issueUrl?: string\n  reason?: string\n}\n\nexport interface ValidationRecord {\n  repositoryId: number\n  sourceSha: string | null\n  sourcePushedAt: string\n  updatedAt: string\n  dshVersion?: string\n  platform?: string\n  validatorVersion?: string\n  disposition?: ValidationRecordDisposition\n  sourceClassification?: SourceClassification\n  structure: ValidationStageEvidence\n  sandbox: ValidationStageEvidence\n}\n\nexport interface ValidationFeed {\n  schemaVersion: 1\n  generatedAt: string\n  records: ValidationRecord[]\n}\n\nexport interface ValidationStatus {\n  overall: ValidationOverall\n  label: string\n  tone: ValidationTone\n  level: 1 | 2 | 3 | 4\n  eligible: boolean\n  verified: boolean\n  updatedAt: string | null\n  sourceSha: string | null\n  dshVersion: string | null\n  platform: string | null\n  validatorVersion: string | null\n  reportUrl: string | null\n  issueUrl: string | null\n  reason: string | null\n  stages: Record<ValidationStageId, ValidationStageEvidence>\n}\n\nconst ELIGIBLE_PROJECT_TYPES = new Set<ProjectType>(['plugin', 'skill', 'collection', 'channel'])\nconst STAGE_STATUSES = new Set<ValidationStageStatus>([\n  'pending',\n  'running',\n  'passed',\n  'failed',\n  'inconclusive',\n  'quarantined',\n  'skipped',\n])\nconst STATUS_DEFINITION_BY_ID = new Map(\n  VALIDATION_STATUS_DEFINITIONS.map((definition) => [definition.id, definition]),\n)\nconst VALIDATION_RECORD_DISPOSITIONS = new Set<ValidationRecordDisposition>([\n  'verified',\n  'auto_failed',\n  'retryable',\n  'capability_pending',\n  'external_dependency_pending',\n  'manual_review',\n])\nconst STATUS_TONES: Record<ValidationOverall, ValidationTone> = {\n  unrecognized: 'neutral',\n  'check-pending': 'neutral',\n  'check-running': 'running',\n  'check-failed': 'danger',\n  'sandbox-pending': 'warning',\n  'sandbox-running': 'running',\n  'sandbox-failed': 'danger',\n  verified: 'success',\n  expired: 'warning',\n  recorded: 'info',\n  retrying: 'running',\n  'capability-pending': 'info',\n  'external-dependency': 'info',\n  inconclusive: 'warning',\n  'security-review': 'warning',\n  'not-applicable': 'neutral',\n}\n\nfunction isRecord(value: unknown): value is Record<string, unknown> {\n  return value !== null && typeof value === 'object' && !Array.isArray(value)\n}\n\nfunction isValidDate(value: unknown): value is string {\n  return typeof value === 'string' && !Number.isNaN(Date.parse(value))\n}\n\nfunction parseStage(value: unknown, field: string): ValidationStageEvidence {\n  if (!isRecord(value) || !STAGE_STATUSES.has(value.status as ValidationStageStatus)) {\n    throw new Error(`${field} 状态无效`)\n  }\n  for (const key of ['checkedAt', 'reportUrl', 'issueUrl', 'reason']) {\n    if (value[key] !== undefined && typeof value[key] !== 'string') {\n      throw new Error(`${field}.${key} 必须是字符串`)\n    }\n  }\n  if (value.checkedAt !== undefined && !isValidDate(value.checkedAt)) {\n    throw new Error(`${field}.checkedAt 不是有效时间`)\n  }\n  return {\n    status: value.status as ValidationStageStatus,\n    ...(value.checkedAt ? { checkedAt: value.checkedAt as string } : {}),\n    ...(value.reportUrl ? { reportUrl: value.reportUrl as string } : {}),\n    ...(value.issueUrl ? { issueUrl: value.issueUrl as string } : {}),\n    ...(value.reason ? { reason: value.reason as string } : {}),\n  }\n}\n\nexport function parseValidationFeed(value: unknown): Map<number, ValidationRecord> {\n  if (!isRecord(value) || value.schemaVersion !== 1 || !isValidDate(value.generatedAt) || !Array.isArray(value.records)) {\n    throw new Error('验证状态文件格式无效')\n  }\n\n  const records = new Map<number, ValidationRecord>()\n  for (const raw of value.records) {\n    if (!isRecord(raw) || !Number.isSafeInteger(raw.repositoryId) || Number(raw.repositoryId) <= 0) {\n      throw new Error('验证记录 repositoryId 无效')\n    }\n    const repositoryId = Number(raw.repositoryId)\n    if (records.has(repositoryId)) throw new Error(`验证记录 repositoryId ${repositoryId} 重复`)\n    if (raw.sourceSha !== null && (typeof raw.sourceSha !== 'string' || !/^[a-f0-9]{40}$/i.test(raw.sourceSha))) {\n      throw new Error(`验证记录 ${repositoryId} sourceSha 无效`)\n    }\n    const sourceClassification = raw.sourceClassification === undefined || raw.sourceClassification === null\n      ? undefined\n      : parseSourceClassification(raw.sourceClassification)\n    if (sourceClassification !== undefined\n      && (raw.sourceSha === null || sourceClassification.sourceSha !== String(raw.sourceSha).toLowerCase())) {\n      throw new Error(`验证记录 ${repositoryId} 源码分类 sourceSha 不一致`)\n    }\n    if (!isValidDate(raw.sourcePushedAt) || !isValidDate(raw.updatedAt)) {\n      throw new Error(`验证记录 ${repositoryId} 时间无效`)\n    }\n    if (raw.disposition !== undefined && !VALIDATION_RECORD_DISPOSITIONS.has(raw.disposition as ValidationRecordDisposition)) {\n      throw new Error(`验证记录 ${repositoryId} disposition 无效`)\n    }\n\n    const structure = parseStage(raw.structure, `验证记录 ${repositoryId}.structure`)\n    const sandbox = parseStage(raw.sandbox, `验证记录 ${repositoryId}.sandbox`)\n    if (!['pending', 'skipped'].includes(sandbox.status) && structure.status !== 'passed') {\n      throw new Error(`验证记录 ${repositoryId} 未通过结构检查，不能写入实机验证结果`)\n    }\n    if (sandbox.status === 'passed' && (raw.sourceSha === null\n      || typeof raw.dshVersion !== 'string' || raw.dshVersion.length === 0\n      || typeof raw.platform !== 'string' || raw.platform.length === 0\n      || typeof raw.validatorVersion !== 'string' || raw.validatorVersion.length === 0)) {\n      throw new Error(`验证记录 ${repositoryId} 缺少完整验证绑定`)\n    }\n\n    records.set(repositoryId, {\n      repositoryId,\n      sourceSha: raw.sourceSha as string | null,\n      sourcePushedAt: raw.sourcePushedAt,\n      updatedAt: raw.updatedAt,\n      ...(typeof raw.dshVersion === 'string' ? { dshVersion: raw.dshVersion } : {}),\n      ...(typeof raw.platform === 'string' ? { platform: raw.platform } : {}),\n      ...(typeof raw.validatorVersion === 'string' ? { validatorVersion: raw.validatorVersion } : {}),\n      ...(raw.disposition === undefined ? {} : { disposition: raw.disposition as ValidationRecordDisposition }),\n      ...(sourceClassification ? { sourceClassification } : {}),\n      structure,\n      sandbox,\n    })\n  }\n  return records\n}\n\nfunction resolveOverall(record: ValidationRecord): ValidationOverall {\n  if (record.structure.status === 'pending') return 'check-pending'\n  if (record.structure.status === 'running') return 'check-running'\n  if (record.structure.status === 'failed') return 'check-failed'\n  if (record.structure.status === 'quarantined') return 'security-review'\n  if (record.disposition === 'retryable') return 'retrying'\n  if (record.disposition === 'capability_pending') return 'capability-pending'\n  if (record.disposition === 'external_dependency_pending') return 'external-dependency'\n  if (record.structure.status === 'inconclusive') return 'inconclusive'\n  if (record.sandbox.status === 'pending' || record.sandbox.status === 'skipped') return 'sandbox-pending'\n  if (record.sandbox.status === 'running') return 'sandbox-running'\n  if (record.sandbox.status === 'failed') return 'sandbox-failed'\n  if (record.sandbox.status === 'inconclusive') return 'inconclusive'\n  return record.sourceSha === null ? 'recorded' : 'verified'\n}\n\nfunction getEvidence(record: ValidationRecord | undefined, key: 'reportUrl' | 'issueUrl' | 'reason'): string | null {\n  return record?.sandbox[key] ?? record?.structure[key] ?? null\n}\n\nfunction buildExpiryReason(record: ValidationRecord, repositoryPushedAt: string): string {\n  const reasons: string[] = []\n  if (record.sourcePushedAt !== repositoryPushedAt) reasons.push('仓库源码已更新')\n  const targetChanged = record.dshVersion !== CURRENT_VALIDATION_TARGET.dshVersion\n    || record.platform !== CURRENT_VALIDATION_TARGET.platform\n    || record.validatorVersion !== CURRENT_VALIDATION_TARGET.validatorVersion\n  if (targetChanged) reasons.push('验证目标已变化')\n  return reasons.join('；') || '验证绑定已失效'\n}\n\nexport function buildValidationStatus({\n  projectType,\n  repositoryPushedAt,\n  record,\n  legacyVerificationUrl = null,\n}: {\n  repositoryId: number\n  projectType: ProjectType\n  repositoryPushedAt: string\n  record?: ValidationRecord\n  legacyVerificationUrl?: string | null\n}): ValidationStatus {\n  const identified = projectType !== 'unknown'\n  const eligible = ELIGIBLE_PROJECT_TYPES.has(projectType)\n  const defaultStages: ValidationStatus['stages'] = {\n    discovery: { status: 'passed' },\n    identification: { status: identified ? 'passed' : 'pending' },\n    structure: { status: eligible ? 'pending' : 'skipped' },\n    sandbox: { status: eligible ? 'pending' : 'skipped' },\n  }\n\n  let overall: ValidationOverall\n  let level: ValidationStatus['level'] = 1\n  let stages = defaultStages\n  let reason: string | null = null\n  if (record && record.sourcePushedAt !== repositoryPushedAt) {\n    stages = { ...defaultStages, structure: record.structure, sandbox: record.sandbox }\n    overall = 'expired'\n    reason = buildExpiryReason(record, repositoryPushedAt)\n    level = record.sandbox.status === 'passed' ? 4 : record.structure.status === 'passed' ? 3 : 2\n  } else if (!identified) {\n    overall = 'unrecognized'\n  } else if (!eligible) {\n    overall = 'not-applicable'\n    level = 2\n  } else if (record) {\n    stages = { ...defaultStages, structure: record.structure, sandbox: record.sandbox }\n    overall = resolveOverall(record)\n    reason = getEvidence(record, 'reason')\n    level = record.structure.status === 'passed' ? 3 : 2\n    if (record.sandbox.status === 'passed') level = 4\n    if (overall === 'verified' && (\n      record.dshVersion !== CURRENT_VALIDATION_TARGET.dshVersion\n      || record.platform !== CURRENT_VALIDATION_TARGET.platform\n      || record.validatorVersion !== CURRENT_VALIDATION_TARGET.validatorVersion\n    )) overall = 'expired'\n    if (overall === 'expired') reason = buildExpiryReason(record, repositoryPushedAt)\n  } else if (legacyVerificationUrl) {\n    overall = 'recorded'\n    level = 4\n    stages = {\n      ...defaultStages,\n      structure: { status: 'passed', reportUrl: legacyVerificationUrl },\n      sandbox: { status: 'passed', reportUrl: legacyVerificationUrl },\n    }\n  } else {\n    overall = 'check-pending'\n    level = 2\n  }\n\n  return {\n    overall,\n    label: STATUS_DEFINITION_BY_ID.get(overall)?.label ?? overall,\n    tone: STATUS_TONES[overall],\n    level,\n    eligible,\n    verified: overall === 'verified',\n    updatedAt: record?.updatedAt ?? null,\n    sourceSha: record?.sourceSha ?? null,\n    dshVersion: record?.dshVersion ?? null,\n    platform: record?.platform ?? null,\n    validatorVersion: record?.validatorVersion ?? null,\n    reportUrl: getEvidence(record, 'reportUrl') ?? legacyVerificationUrl,\n    issueUrl: getEvidence(record, 'issueUrl'),\n    reason,\n    stages,\n  }\n}\n"
