    {
      "path": ".github/workflows/validate-plugins.yml",
      "content": "name: Validate plugins\n\non:\n  workflow_run:\n    workflows: [Classify plugins]\n    types: [completed]\n  workflow_dispatch:\n    inputs:\n      force_full:\n        description: Revalidate every repository in the classified validation catalog\n        required: false\n        default: false\n        type: boolean\n\npermissions:\n  actions: read\n  contents: read\n\nconcurrency:\n  group: plugin-validation-publication\n  cancel-in-progress: false\n\njobs:\n  prepare:\n    runs-on: ubuntu-latest\n    env:\n      GH_TOKEN: ${{ secrets.GITHUB_TOKEN }}\n      CLASSIFICATION_RUN_ID: ${{ github.event_name == 'workflow_run' && github.event.workflow_run.id || '' }}\n      CLASSIFICATION_BRANCH: ${{ github.event_name == 'workflow_run' && github.event.workflow_run.head_branch || github.ref_name }}\n    steps:\n      - name: Stop after a failed classification run\n        if: github.event_name == 'workflow_run' && github.event.workflow_run.conclusion != 'success'\n        run: |\n          echo \"Classification workflow did not succeed: ${{ github.event.workflow_run.conclusion }}\"\n          exit 1\n\n      - name: Checkout validation source\n        uses: actions/checkout@v5\n        with:\n          ref: ${{ github.event_name == 'workflow_run' && github.event.workflow_run.head_sha || github.ref }}\n\n      - name: Set up Node.js\n        uses: actions/setup-node@v5\n        with:\n          node-version: 22\n          cache: npm\n\n      - name: Install dependencies\n        run: npm ci\n\n      - name: Resolve latest catalog, discovery, validation, and classification artifacts\n        run: |\n          mkdir -p validation-input/previous\n          mkdir -p /tmp/dsh-validation-history\n          if test -f src/data/source-classification.json; then\n            cp src/data/source-classification.json /tmp/dsh-validation-history/checked-in.json\n          fi\n          catalog_found=false\n          discovery_found=false\n          sync_run_ids=\"$(gh run list --workflow sync-catalog.yml --branch main --status success --limit 20 --json databaseId --jq '.[].databaseId' 2>/dev/null || true)\"\n          for run_id in $sync_run_ids; do\n            catalog_dir=\"/tmp/dsh-catalog-$run_id\"\n            if test \"$catalog_found\" = false \\\n              && gh run download \"$run_id\" --name plugin-catalog-snapshot --dir \"$catalog_dir\" 2>/dev/null \\\n              && test -f \"$catalog_dir/catalog.json\"; then\n              cp \"$catalog_dir/catalog.json\" validation-input/catalog.json\n              catalog_found=true\n            fi\n            discovery_dir=\"/tmp/dsh-discovery-$run_id\"\n            if test \"$discovery_found\" = false \\\n              && gh run download \"$run_id\" --name plugin-discovery-snapshot --dir \"$discovery_dir\" 2>/dev/null \\\n              && test -f \"$discovery_dir/discovery.json\"; then\n              cp \"$discovery_dir/discovery.json\" validation-input/discovery.json\n              discovery_found=true\n            fi\n            if test \"$catalog_found\" = true && test \"$discovery_found\" = true; then break; fi\n          done\n          if test \"$catalog_found\" = false; then cp src/data/catalog.json validation-input/catalog.json; fi\n          if test \"$discovery_found\" = false; then cp validation-input/catalog.json validation-input/discovery.json; fi\n\n          state_found=false\n          validation_run_ids=\"$(gh run list --workflow validate-plugins.yml --branch main --status success --limit 20 --json databaseId --jq '.[].databaseId' 2>/dev/null || true)\"\n          for run_id in $validation_run_ids; do\n            artifact_dir=\"/tmp/dsh-validation-state-$run_id\"\n            if gh run download \"$run_id\" --name plugin-validation-state --dir \"$artifact_dir\" 2>/dev/null \\\n              && test -f \"$artifact_dir/state.json\" \\\n              && test -f \"$artifact_dir/validation.json\" \\\n              && test -f \"$artifact_dir/source-classification.json\" \\\n              && find \"$artifact_dir/canary\" -type f -name '*.json' -print -quit | grep -q .; then\n              cp \"$artifact_dir/source-classification.json\" \"/tmp/dsh-validation-history/$run_id.json\"\n              if test \"$state_found\" = false; then\n                cp -R \"$artifact_dir/.\" validation-input/previous/\n                state_found=true\n              fi\n            fi\n          done\n          if test \"$state_found\" = true; then\n            cp validation-input/previous/validation.json validation-input/previous-validation.json\n          else\n            cp src/data/validation.json validation-input/previous-validation.json\n          fi\n\n          classification_found=false\n          classification_discovery_found=false\n          if test -n \"$CLASSIFICATION_RUN_ID\"; then\n            completed_run_ids=\"$CLASSIFICATION_RUN_ID\"\n          else\n            completed_run_ids=\"$(gh run list --workflow classify-plugins.yml --branch \"$CLASSIFICATION_BRANCH\" --limit 30 --json databaseId --jq '.[].databaseId' 2>/dev/null || true)\"\n          fi\n          for run_id in $completed_run_ids; do\n            run_metadata=\"$(gh run view \"$run_id\" --json workflowName,headBranch,status,conclusion 2>/dev/null || true)\"\n            if [[ -z \"$run_metadata\" ]] || ! printf '%s' \"$run_metadata\" | EXPECTED_BRANCH=\"$CLASSIFICATION_BRANCH\" node -e '\n              const fs = require(\"node:fs\")\n              const metadata = JSON.parse(fs.readFileSync(0, \"utf8\"))\n              process.exit(metadata.workflowName === \"Classify plugins\"\n                && metadata.headBranch === process.env.EXPECTED_BRANCH\n                && metadata.status === \"completed\"\n                && [\"success\", \"failure\", \"cancelled\", \"timed_out\"].includes(metadata.conclusion) ? 0 : 1)\n            '; then\n              continue\n            fi\n            artifact_dir=\"/tmp/dsh-classification-state-$run_id\"\n            if gh run download \"$run_id\" --name plugin-classification-state --dir \"$artifact_dir\" 2>/dev/null \\\n              && test -f \"$artifact_dir/source-classification.json\" \\\n              && test -f \"$artifact_dir/validation-catalog.json\" \\\n              && test -f \"$artifact_dir/discovery.json\"; then\n              cp \"$artifact_dir/source-classification.json\" validation-input/source-classification.json\n              cp \"$artifact_dir/validation-catalog.json\" validation-input/validation-catalog.json\n              cp \"$artifact_dir/discovery.json\" validation-input/discovery.json\n              classification_discovery_found=true\n              classification_found=true\n              break\n            fi\n          done\n          if test \"$classification_found\" = false; then\n            echo 'No completed classified validation catalog is available; validation is deferred.' >&2\n            exit 1\n          fi\n          if test \"$classification_discovery_found\" != true; then\n            echo 'Classified validation catalog has no paired discovery snapshot; validation is deferred.' >&2\n            exit 1\n          fi\n\n      - name: Verify atomic validation input snapshots\n        run: |\n          npm run --silent validate:input -- \\\n            --discovery validation-input/discovery.json \\\n            --validation-catalog validation-input/validation-catalog.json \\\n            --classification validation-input/source-classification.json \\\n            --validation-history-directory /tmp/dsh-validation-history\n\n      - name: Upload immutable validation input\n        uses: actions/upload-artifact@v6\n        with:\n          name: plugin-validation-input\n          path: validation-input/\n          if-no-files-found: error\n          retention-days: 30\n\n  select:\n    needs: prepare\n    outputs:\n      has_changes: ${{ steps.selection.outputs.has_changes }}\n      first_run: ${{ steps.selection.outputs.first_run }}\n      shards: ${{ steps.selection.outputs.shards }}\n    env:\n      FORCE_FULL: ${{ github.event_name == 'workflow_dispatch' && inputs.force_full || false }}\n    runs-on: ubuntu-latest\n    steps:\n      - name: Checkout validation source\n        uses: actions/checkout@v5\n\n      - name: Download validation input\n        uses: actions/download-artifact@v7\n        with:\n          name: plugin-validation-input\n          path: validation-input\n\n      - name: Set up Node.js\n        uses: actions/setup-node@v5\n        with:\n          node-version: 22\n          cache: npm\n\n      - name: Install dependencies\n        run: npm ci\n\n      - name: Select full or incremental validation set from classified catalog\n        id: selection\n        run: |\n          previous_args=()\n          classification_mode=\"$(node -e 'const fs=require(\"fs\"); const archive=JSON.parse(fs.readFileSync(\"validation-input/source-classification.json\",\"utf8\")); process.stdout.write(archive.mode === \"full\" ? \"full\" : \"incremental\")')\"\n          if test \"$FORCE_FULL\" != \"true\" && test \"$classification_mode\" != \"full\" && test -f validation-input/previous/state.json; then\n            previous_args=(--previous validation-input/previous/state.json)\n          fi\n          npm run --silent validate:select -- \\\n            --catalog validation-input/validation-catalog.json \\\n            --baseline validation/baseline.json \\\n            --previous-feed validation-input/previous-validation.json \\\n            --output validation-input/selection.json \\\n            --shard-count 20 \\\n            \"${previous_args[@]}\" > validation-input/selection-summary.json\n          npm run --silent validate:input -- \\\n            --discovery validation-input/discovery.json \\\n            --validation-catalog validation-input/validation-catalog.json \\\n            --selection validation-input/selection.json\n          node -e 'const fs=require(\"fs\"); const summary=JSON.parse(fs.readFileSync(\"validation-input/selection-summary.json\",\"utf8\")); fs.appendFileSync(process.env.GITHUB_OUTPUT,\"has_changes=\"+String(summary.repositoryCount>0)+\"\\nfirst_run=\"+String(summary.firstRun)+\"\\nshards=\"+JSON.stringify(summary.shards)+\"\\n\")'\n\n      - name: Upload classified validation selection\n        uses: actions/upload-artifact@v6\n        with:\n          name: plugin-validation-selection\n          path: validation-input/selection.json\n          if-no-files-found: error\n          retention-days: 30\n\n  baseline:\n    needs: select\n    if: needs.select.outputs.has_changes == 'true'\n    runs-on: ubuntu-latest\n    timeout-minutes: 360\n    env:\n      GH_TOKEN: ${{ secrets.GITHUB_TOKEN }}\n    steps:\n      - name: Checkout validation source\n        uses: actions/checkout@v5\n\n      - name: Download validation input and selection\n        uses: actions/download-artifact@v7\n        with:\n          pattern: plugin-validation-*\n          path: validation-input\n          merge-multiple: true\n\n      - name: Restore catalog snapshot\n        run: cp validation-input/catalog.json src/data/catalog.json\n\n      - name: Set up Node.js\n        uses: actions/setup-node@v5\n        with:\n          node-version: 22\n          cache: npm\n\n      - name: Install dependencies\n        run: npm ci\n\n      - name: Run initial 20-target canary serially\n        if: needs.select.outputs.first_run == 'true'\n        run: >-\n          npm run validate:baseline --\n          --output validation/reports/canary\n          --limit 0\n\n      - name: Reuse compatible canary evidence\n        if: needs.select.outputs.first_run != 'true'\n        run: |\n          mkdir -p validation/reports/canary\n          cp -R validation-input/previous/canary/. validation/reports/canary/\n\n      - name: Enforce canary promotion gate\n        run: |\n          npm run --silent validate:promote -- \\\n            --reports validation/reports/canary > /tmp/canary-gate.json\n          node -e \"const result=require('/tmp/canary-gate.json'); if(!result.assessment.eligible){console.error(result.assessment.reasons.join(',')); process.exit(1)}\"\n\n      - name: Upload current canary reports\n        if: always()\n        uses: actions/upload-artifact@v6\n        with:\n          name: plugin-validation-canary-current\n          path: validation/reports/canary/\n          if-no-files-found: error\n          retention-days: 30\n\n  validate:\n    # Baseline is validator-health telemetry. It must not prevent per-plugin\n    # evidence from being collected and archived.\n    needs: [select]\n    if: needs.select.outputs.has_changes == 'true'\n    runs-on: ubuntu-latest\n    timeout-minutes: 360\n    strategy:\n      fail-fast: false\n      max-parallel: 6\n      matrix:\n        shard: ${{ fromJSON(needs.select.outputs.shards) }}\n    env:\n      GH_TOKEN: ${{ secrets.GITHUB_TOKEN }}\n      DSH_VALIDATION_VERSION: 0.1.0-rc.6\n      VALIDATOR_VERSION: 0.1.2\n      VALIDATION_STRUCTURE_CONCURRENCY: 2\n      VALIDATION_CANDIDATE_CONCURRENCY: 2\n    steps:\n      - name: Checkout validation source\n        uses: actions/checkout@v5\n\n      - name: Download validation input and selection\n        uses: actions/download-artifact@v7\n        with:\n          pattern: plugin-validation-*\n          path: validation-input\n          merge-multiple: true\n\n      - name: Restore catalog snapshot\n        run: cp validation-input/catalog.json src/data/catalog.json\n\n      - name: Set up Node.js\n        uses: actions/setup-node@v5\n        with:\n          node-version: 22\n          cache: npm\n\n      - name: Install dependencies\n        run: npm ci\n\n      - name: Run selected P1 structure shard with bounded concurrency\n        run: |\n          npm run --silent validate:shadow -- \\\n            --output validation/reports/structure \\\n            --discovery validation-input/discovery.json \\\n            --selection validation-input/selection.json \\\n            --shard-index \"${{ matrix.shard }}\" \\\n            --shard-count 20 \\\n            --limit 0 | tee /tmp/shadow-summary.json\n          node -e \"const result=require('/tmp/shadow-summary.json'); if(result.reportsWritten > result.discovered){console.error('P1 reports exceed discovery count'); process.exit(1)}; if(result.loadFailures.length || result.reportsWritten !== result.discovered){console.warn('P1 shard completed with retryable snapshot omissions', JSON.stringify({discovered:result.discovered,reportsWritten:result.reportsWritten,loadFailures:result.loadFailures.map(({repositoryId,code})=>({repositoryId,code}))}))}\"\n\n      - name: Run selected sandbox candidates with bounded concurrency\n        run: >-\n          npm run validate:candidates --\n          --reports validation/reports/structure\n          --output validation/reports/candidates\n\n      - name: Upload sanitized structure and runtime reports\n        if: always()\n        uses: actions/upload-artifact@v6\n        with:\n          name: plugin-validation-candidates-${{ matrix.shard }}\n          path: validation/reports/\n          if-no-files-found: error\n          retention-days: 30\n\n  promote:\n    needs: [select, baseline, validate]\n    if: needs.select.outputs.has_changes == 'true' && needs.baseline.result == 'success' && needs.validate.result == 'success'\n    runs-on: ubuntu-latest\n    timeout-minutes: 30\n    steps:\n      - name: Checkout validation source\n        uses: actions/checkout@v5\n\n      - name: Download validation input and artifacts\n        uses: actions/download-artifact@v7\n        with:\n          pattern: plugin-validation-*\n          path: validation-artifacts\n          merge-multiple: true\n\n      - name: Download current canary reports\n        uses: actions/download-artifact@v7\n        with:\n          name: plugin-validation-canary-current\n          path: validation-artifacts/canary\n\n      - name: Download candidate reports\n        uses: actions/download-artifact@v7\n        with:\n          pattern: plugin-validation-candidates-*\n          path: validation-artifacts/candidates\n          merge-multiple: true\n\n      - name: Set up Node.js\n        uses: actions/setup-node@v5\n        with:\n          node-version: 22\n          cache: npm\n\n      - name: Install dependencies\n        run: npm ci\n\n      - name: Promote incremental SHA-bound evidence\n        run: >-\n          npm run validate:promote --\n          --reports validation-artifacts/candidates\n          --gate-reports validation-artifacts/canary\n          --previous-feed validation-artifacts/previous-validation.json\n          --output validation-state/validation.json\n          --publish\n\n      - name: Advance validation cursor after completed evidence\n        run: >-\n          npm run validate:state --\n          --catalog validation-artifacts/validation-catalog.json\n          --previous validation-artifacts/previous/state.json\n          --selection validation-artifacts/selection.json\n          --reports validation-artifacts/candidates\n          --output validation-state/state.json\n\n      - name: Retain reusable canary evidence\n        run: |\n          mkdir -p validation-state/canary\n          cp -R validation-artifacts/canary/. validation-state/canary/\n\n      - name: Upload successful validation state\n        uses: actions/upload-artifact@v6\n        with:\n          name: plugin-validation-publication\n          path: validation-state/\n          if-no-files-found: error\n          retention-days: 30\n\n  validation-archive:\n    needs: [select, validate, promote]\n    if: always() && needs.select.result == 'success' && needs.select.outputs.has_changes == 'true'\n    runs-on: ubuntu-latest\n    timeout-minutes: 30\n    steps:\n      - name: Checkout validation source\n        uses: actions/checkout@v5\n\n      - name: Download immutable validation input and selection\n        use